    const elBotAction = document.getElementById("bot-action");
    const elBotChange = document.getElementById("bot-change");
    const treeRoot = document.getElementById("tree-root");

    // CONSTRUÇÃO DO TRILHO LATERAL (SIDEBAR AGRUPADA)
    function buildSidebar() {
      const groups = {};
      SCREENS_DATA.forEach((item, index) => {
        if (!groups[item.etapa]) groups[item.etapa] = [];
        groups[item.etapa].push({ ...item, globalIndex: index });
      });

      treeRoot.innerHTML = "";
      for (const etapaKey in groups) {
        const groupEl = document.createElement("div");
        groupEl.className = "tree-group";

        const titleEl = document.createElement("div");
        titleEl.className = "tree-group-title";
        titleEl.textContent = ETAPAS_INFO[etapaKey] ? ETAPAS_INFO[etapaKey].nome : etapaKey;
        groupEl.appendChild(titleEl);

        groups[etapaKey].forEach(item => {
          const itemEl = document.createElement("div");
          itemEl.className = "tree-item";
          itemEl.id = `tree-item-${item.globalIndex}`;
          itemEl.innerHTML = `
            <div class="tree-item-id">${item.id}</div>
            <div class="tree-item-state">${item.estado}</div>
          `;
          itemEl.onclick = () => renderScreen(item.globalIndex);
          groupEl.appendChild(itemEl);
        });

        treeRoot.appendChild(groupEl);
      }
    }

    // RENDERIZAR TELA ATUAL
    function renderScreen(index) {
      if (index < 0 || index >= SCREENS_DATA.length) return;
      currentIndex = index;
      const data = SCREENS_DATA[currentIndex];

      // Oculta todas as telas e ativa a correspondente
      const allCanvases = document.querySelectorAll(".screen-canvas");
      allCanvases.forEach(canvas => {
        if (canvas.getAttribute("data-screen-id") === data.id && canvas.getAttribute("data-estado") === data.estado) {
          canvas.classList.add("active");
        } else {
          canvas.classList.remove("active");
        }
      });

      // Atualiza barra superior
      elScreenId.textContent = data.id;
      elEstadoName.textContent = data.estado;
      elCounter.textContent = `${currentIndex + 1} / ${SCREENS_DATA.length}`;

      const etapaObj = ETAPAS_INFO[data.etapa] || { nome: data.etapa, heading: data.etapa, body: "", fonte: "Spec v3.1" };
      elEtapaName.textContent = etapaObj.nome;

      // Marcas da tela
      elMarks.innerHTML = "";
      if (data.marks.includes("pico")) elMarks.innerHTML += '<span class="mark-tag mark-pico">PICO (Beat 4)</span>';
      if (data.marks.includes("aha")) elMarks.innerHTML += '<span class="mark-tag mark-aha">AHA MOMENT</span>';
      if (data.marks.includes("latch")) elMarks.innerHTML += '<span class="mark-tag mark-latch">LATCH CADEADO</span>';
      if (data.marks.includes("memo")) elMarks.innerHTML += '<span class="mark-tag mark-memo">MEMORÁVEL</span>';
      if (data.marks.includes("gate")) elMarks.innerHTML += '<span class="mark-tag mark-gate">GATE DOCENTE</span>';

      // Atualiza painel da etapa (direita)
      elInfoHeading.textContent = etapaObj.heading;
      elInfoBody.innerHTML = etapaObj.body;
      elInfoFonte.textContent = etapaObj.fonte;

      // Atualiza rodapé
      elBotScreen.textContent = `${data.id} · ${data.screenName}`;
      elBotAction.textContent = data.action;
      elBotChange.textContent = data.change;

      // Atualiza trilho lateral
      document.querySelectorAll(".tree-item").forEach(el => el.classList.remove("active"));
      const activeTreeEl = document.getElementById(`tree-item-${currentIndex}`);
      if (activeTreeEl) {
        activeTreeEl.classList.add("active");
        activeTreeEl.scrollIntoView({ block: "nearest", behavior: "smooth" });
      }
    }

    // BOTÕES DE NAVEGAÇÃO
    document.getElementById("btn-prev").onclick = () => {
      if (currentIndex > 0) renderScreen(currentIndex - 1);
    };
    document.getElementById("btn-next").onclick = () => {
      if (currentIndex < SCREENS_DATA.length - 1) renderScreen(currentIndex + 1);
    };

    // NAVEGAÇÃO VIA TECLADO (SETAS)
    window.addEventListener("keydown", (e) => {
      if (e.key === "ArrowLeft") {
        if (currentIndex > 0) renderScreen(currentIndex - 1);
      } else if (e.key === "ArrowRight") {
        if (currentIndex < SCREENS_DATA.length - 1) renderScreen(currentIndex + 1);
      }
    });

    // SIMULAÇÃO INTERATIVA DE MOMENTOS SCRIPTADOS
    document.getElementById("btn-demo-script").onclick = () => {
      const data = SCREENS_DATA[currentIndex];

      // Simulação de build empacotando (E3-ALU-02 empacotando_build -> latch_travado)
      if (data.id === "E3-ALU-02" && data.estado === "empacotando_build") {
        const nextIdx = SCREENS_DATA.findIndex(s => s.id === "E3-ALU-02" && s.estado === "latch_travado");
        if (nextIdx !== -1) renderScreen(nextIdx);
        return;
      }

      // Simulação do teste de regressão (E5-ALU-03 teste_executando -> sucesso_restabelecido)
      if (data.id === "E5-ALU-03" && data.estado === "teste_executando") {
        const nextIdx = SCREENS_DATA.findIndex(s => s.id === "E5-ALU-03" && s.estado === "sucesso_restabelecido");
        if (nextIdx !== -1) renderScreen(nextIdx);
        return;
      }

      // Simulação de avanço padrão para o próximo estado da mesma tela ou próxima tela
      if (currentIndex < SCREENS_DATA.length - 1) {
        renderScreen(currentIndex + 1);
      }
    };

    // CLIQUE NOS BOTÕES DENTRO DOS QUADROS PARA AVANÇO NATURAL
    document.addEventListener("click", (e) => {
      const target = e.target;
      if (target.tagName === "BUTTON" && target.classList.contains("uai-btn") && !target.classList.contains("desabilitado")) {
        // Concessão da demo declarada para prosseguir
        if (currentIndex < SCREENS_DATA.length - 1) {
          renderScreen(currentIndex + 1);
        }
      }
    });

    // INICIALIZAÇÃO
    buildSidebar();
    renderScreen(0);
  </script>
</body>
</html>
